import{z as r,x as A,o as E,c as s,q as e,j as l,D as B,d as t,s as n,S as c}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"warp 级原语","description":"","frontmatter":{"title":"warp 级原语","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/gpu-warp-primitives.md","filePath":"cs/gpu-warp-primitives.md","lastUpdated":1791413859000}'),p={name:"cs/gpu-warp-primitives.md"};function i(d,a,_,m,f,D){const o=A("Mermaid");return E(),s("div",null,[a[1]||(a[1]=e('<h1 id="warp-级原语" tabindex="-1">warp 级原语 <a class="header-anchor" href="#warp-级原语" aria-label="Permalink to &quot;warp 级原语&quot;">​</a></h1><div class="epigraph"><p>warp 内部有一条不经过任何存储的邮路：shuffle 把一个寄存器直接送到另一个 lane，一拍即达——代价是邮路半径只有 32。</p><footer>—— 据 NVIDIA CUDA C++ Programming Guide 的 Warp Shuffle 与 Vote 函数、PTX ISA 文档整理</footer></div><p><a href="/cs/gpu-memory-hierarchy-practice">上一课</a>把字节放到了对层，但层次解决的是「到哪取数」；warp 内部的交换还有一条更窄的路。缺口在归约这类模式上：32 个 lane 各持一个部分和，要互相传递——走 smem 就要算地址、过屏障、挨 bank 的账，而交换半径只有 32。本栏的 <a href="/cs/gpu-simt">SIMT</a> 已经说了 lane 共享一个 warp 的执行；大模型栏的 <a href="/llm/warp-specialization">Warp specialization</a> 讲的是 warp 之间的角色分工。本课在 warp 内部：shuffle 与 vote 两个家族，以及它们把哪些存储流量整个消掉。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>warp 归约的朴素写法把 smem 当公告板：每步一半 lane 写自己的部分和、另一半读邻居的，步与步之间插 <code>__syncthreads</code>。每一步交换都付三重税：地址计算与 bank 规划、屏障的等待、以及访存指令本身。可交换的范围其实只有一个 warp——lane 之间的寄存器本来就近在咫尺。缺口是：哪些通信能沉到 warp 内、用什么原语沉、沉下去之后省掉的是哪几重税。判断反了（该走 smem 的跨 warp 通信硬塞进 shuffle）会在编译期就报错；判断漏了（warp 内通信仍走 smem）则白付三重税。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>shuffle 家族按「谁拿到谁的值」分类。<code>__shfl_sync(mask, v, srcLane)</code> 直接指定源 lane；<code>__shfl_up_sync</code> / <code>__shfl_down_sync</code> 做扫描式的邻居交换；<code>__shfl_xor_sync(v, k)</code> 与 lane \\(i\\oplus k\\) 交换——butterfly 模式，第 \\(0,1,2,3,4\\) 步取 \\(k=1,2,4,8,16\\)，五步之后 32 个 lane 全部持有总和，一条 warp 全归约就此完成，全程没有一条存储指令。<span class="marginnote">「xor 交换」翻译成大白话：每个 lane 找与自己编号二进制恰好差一位的伙伴互换数据——第 1 步差最后一位（0↔1、2↔3，相邻成对），第 2 步差倒数第二位（0↔2，跨 2）……像锦标赛：32 人五轮交换后，人人都知道了总分，且没碰过一次内存。</span><code>width</code> 参数把交换限制在宽度为 \\(2^j\\) 的子组内，分段归约不用再写循环。</p><p>vote 家族把判断折叠成位图。<code>__ballot_sync(mask, p)</code> 返回一个 32 位整数，第 \\(i\\) 位是 lane \\(i\\) 谓词的值；<code>__any_sync</code> / <code>__all_sync</code> 直接归约成布尔；<code>__match_any_sync</code> 找出同值的 lane 组。典型用法：先 ballot 拿到「谁需要走慢路径」，再决定是分裂还是统一走——把「两条路径各跑一遍」的发散成本（第一课的相加账）压成一次位测试加一条路径。<span class="marginnote">数字实例：lane 0、5、9 的谓词为真时，ballot 返回 \\(2^0+2^5+2^9=1+32+512=545\\)。一条 <code>v == 0</code> 判断「全假」，<code>v &amp; (v-1)</code> 循环数「有几个真」——原本要靠 warp 发散两轮才能摸清的局面，变成对一个整数的算术。</span></p>',8)),(E(),l(c,null,{default:B(()=>[n(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22warp%20%E5%86%85%E6%9D%A1%E4%BB%B6%E5%88%A4%E6%96%AD%20p%22%5D%20--%3E%20DIV%5B%22%E6%9C%B4%E7%B4%A0%E5%86%99%E6%B3%95%EF%BC%9A%E4%B8%A4%E6%9D%A1%E8%B7%AF%E5%BE%84%E5%90%84%E8%B7%91%E4%B8%80%E9%81%8D%22%5D%0A%20%20DIV%20--%3E%20TAIL%5B%22%E9%95%BF%E5%B0%BE%20warp%20%E6%8B%96%E5%85%A8%E5%9C%BA%22%5D%0A%20%20P%20--%3E%20BAL%5B%22ballot%EF%BC%9A%E4%B8%80%E6%9D%A1%E6%8C%87%E4%BB%A4%E6%8B%BF%E5%88%B0%2032%20%E4%BD%8D%E4%BD%8D%E5%9B%BE%22%5D%0A%20%20BAL%20--%3E%20T%7B%22%E4%BD%8D%E5%9B%BE%E8%AF%BB%E6%95%B0%EF%BC%9A%E5%85%A8%E4%B8%80%E8%87%B4%E5%90%97%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E5%85%A8%200%20%E6%88%96%E5%85%A8%201%22%7C%20UNI%5B%22%E6%95%B4%20warp%20%E7%BB%9F%E4%B8%80%E8%B5%B0%E4%B8%80%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20T%20--%3E%7C%22%E6%B7%B7%E5%90%88%22%7C%20SPLIT%5B%22%E6%8C%89%E4%BD%8D%E5%88%86%E7%BB%84%EF%BC%8C%E6%88%96%E7%BB%9F%E4%B8%80%E8%B5%B0%E6%85%A2%E8%B7%AF%E5%BE%84%22%5D%0A%20%20UNI%20--%3E%20DONE%5B%22%E5%8F%91%E6%95%A3%E6%88%90%E6%9C%AC%E5%8E%8B%E6%88%90%E4%B8%80%E6%AC%A1%E4%BD%8D%E6%B5%8B%E8%AF%95%22%5D%0A%20%20SPLIT%20--%3E%20DONE%0A%60%60%60%60mask%60%20%E5%8F%82%E6%95%B0%E6%98%AF%20Volta%20%E7%8B%AC%E7%AB%8B%E7%BA%BF%E7%A8%8B%E8%B0%83%E5%BA%A6%E5%9C%A8%20API%20%E4%B8%8A%E7%9A%84%E8%90%BD%E7%82%B9%EF%BC%9A%E5%8F%82%E4%B8%8E%E4%BA%A4%E6%8D%A2%E7%9A%84%20lane%20%E5%BF%85%E9%A1%BB%E4%BB%A5%E5%90%8C%E4%B8%80%20mask%20%E6%89%A7%E8%A1%8C%E5%90%8C%E4%B8%80%E8%AF%AD%E5%8F%A5%EF%BC%8Cmask%20%E4%B8%8D%E6%BB%A1%E6%98%AF%E6%9C%AA%E5%AE%9A%E4%B9%89%E8%A1%8C%E4%B8%BA%EF%BC%8C%E4%B8%8D%E5%86%8D%E6%98%AF%E8%80%81%E5%8D%A1%E4%B8%8A%E7%9A%84%E3%80%8C%E7%A2%B0%E5%B7%A7%E8%83%BD%E8%B7%91%E3%80%8D%E3%80%82%0A%0A%60%60%60mermaid%0Aflowchart%20TD%0A%20%20IN%5B%2232%20%E4%B8%AA%20lane%20%E5%90%84%E6%8C%81%E4%B8%80%E4%B8%AA%E5%80%BC%22%5D%20--%3E%20X1%5B%22xor%201%EF%BC%9A%E4%B8%8E%E7%9B%B8%E9%82%BB%20lane%20%E4%BA%A4%E6%8D%A2%EF%BC%8C16%20%E5%AF%B9%22%5D%0A%20%20X1%20--%3E%20X2%5B%22xor%202%EF%BC%9A%E8%B7%A8%202%20%E4%BA%A4%E6%8D%A2%EF%BC%8C8%20%E5%AF%B9%22%5D%0A%20%20X2%20--%3E%20X4%5B%22xor%204%20%E4%B8%8E%20xor%208%20%E4%B8%8E%20xor%2016%22%5D%0A%20%20X4%20--%3E%20OUT%5B%22%E4%BA%94%E6%AD%A5%E5%90%8E%2032%20%E4%B8%AA%20lane%20%E5%85%A8%E6%8C%81%E6%80%BB%E5%92%8C%22%5D%0A%20%20ALT%5B%22%E6%9C%B4%E7%B4%A0%E6%96%B9%E6%A1%88%EF%BC%9Asmem%20%E5%85%AC%E5%91%8A%E6%9D%BF%22%5D%20--%3E%20TAX%5B%22%E5%9C%B0%E5%9D%80%E8%AE%A1%E7%AE%97%20%2B%20%E5%B1%8F%E9%9A%9C%20%2B%20bank%20%E8%B4%A6%22%5D%0A"})]),fallback:B(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>快的原因在硬件位置：shuffle 走寄存器堆的 lane 间交换通路，不占访存单元的端口、不进 smem、不需要屏障——上一课说「寄存器零等待」，shuffle 是把零等待用在了通信上。步数是 \\(\\log_2 32 = 5\\)，通信量逐半收缩：\\(16+8+4+2+1\\) 共 31 次成对交换；smem 方案同样五步，但每步多一重屏障税，block 只有一个 warp 时屏障也省不掉（块级屏障要凑齐所有 warp）。vote 的价值同理：ballot 一个指令拿到全部 lane 的谓词，替代「先发散两轮、各自退出」的写法，长尾 warp 不再拖全场。</p><p>迁移到新卡时的注意点在 mask 语义：Ampere 之前 mask 不满常被容忍，之后是未定义——把「全 warp 在场」写成字面量 <code>0xffffffff</code> 而非 <code>__activemask()</code>，因为后者的值取决于执行时刻谁在场，拿它当参与集合是把自己交给调度顺序。<span class="marginnote">常见误区：把 shuffle 当免费且无条件的操作。它是全 warp 的同步语句，mask 里列的每个 lane 都必须执行同一句；写在只有部分 lane 进入的 if 里而不改 mask，结果不是「其他 lane 等着」，是整条语句未定义——新卡上换驱动就可能换答案。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>半径 32 是硬边界：跨 warp 的归约必须回到 smem 加 <code>__syncthreads</code>，那里等着的是下一课的 bank 账。cooperative groups 提供了 <code>reduce</code> 之类的封装，展开后仍是这套原语，语义不新增。scan 的正确性证明（排他性与结合律）是算法层的合同，本课只给机制。发散路径里调 shuffle 要格外小心：不在场的 lane 不会参与，部分活跃 warp 的交换结果按 mask 定义——先想清楚参与集合，再写表达式。</p><p><span class="marginnote"><code>__activemask()</code> 的易错点：它返回的是「执行到这一句时谁在场」，不是「谁应该参与」。用它当 shuffle 的 mask，同一份代码会随调度顺序给出不同结果——正确写法是显式传参与集合，或用 <code>__syncwarp</code> 先对齐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>warp 内通信不必经过存储：shuffle 走寄存器堆的 lane 交换通路，不占访存端口、免屏障。</li><li>butterfly 归约取 \\(k=1,2,4,8,16\\) 五步，32 lane 全持总和；<code>width</code> 参数给出分段子组。</li><li>vote 家族把谓词折叠成位图，ballot 加路径判断替代发散两轮。</li><li>mask 是 Volta 独立线程调度的 API 落点：参与集合必须显式，不满是未定义行为。</li><li>半径 32 是硬边界；跨 warp 回 smem 与屏障，那边的账在下一课。</li><li>出处：NVIDIA CUDA C++ Programming Guide 的 <code>__shfl_*_sync</code> / <code>__ballot_sync</code> 等内建函数章；NVIDIA PTX ISA 文档。</li></ul>',8))])}const u=r(p,[["render",i]]);export{C as __pageData,u as default};
